    const button = await this._button();
    const [checked, pressed] = await parallel(() => [
      button.getAttribute('aria-checked'),
      button.getAttribute('aria-pressed'),
    ]);
    return coerceBooleanProperty(checked) || coerceBooleanProperty(pressed);
  }

